"""Islamiat (Ikhtiari) XII PDF37: pp.64–65 — Al-Hujurat 11-12, la ikraha fi al-din, hadith on ghibah. Run: python class12_iski_page037.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p37():
    b = Builder()
    P(b, [('… you keep holding fast to the Quran and the Sunnah."', 'قرآن و سنت کا دامن تھامے رہو گے“', '… قرآن او سنت ټینګ ونیسئ.»'),
          ('Allah the Exalted has given the lesson of mutual respect and love in verses no. 11 and 12 of Surah al-Hujurat in this way.', 'اللہ تعالیٰ نے باہمی احترام و محبت کا درس سورۃ الحجرات کی آیت نمبر 11 اور 12 میں اس طرح دیا ہے۔', 'الله تعالی د متقابل درناوي او مینې درس د سورة الحجرات په ۱۱ او ۱۲ آیتونو کې داسې ورکړی دی.')])
    AR(b, 'يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوْا لَا يَسْخَرْ قَوْمٌ مِّنْ قَوْمٍ عَسٰٓى اَنْ يَّكُوْنُوْا خَيْرًا مِّنْهُمْ وَلَا نِسَآءٌ مِّنْ نِّسَآءٍ عَسٰٓى اَنْ يَّكُنَّ خَيْرًا مِّنْهُنَّ ۚ وَلَا تَلْمِزُوْٓا اَنْفُسَكُمْ وَلَا تَنَابَزُوْا بِالْاَلْقَابِ ؕ بِئْسَ الِاسْمُ الْفُسُوْقُ بَعْدَ الْاِيْمَانِ ۚ وَمَنْ لَّمْ يَتُبْ فَاُولٰٓئِكَ هُمُ الظّٰلِمُوْنَ ۞ يٰٓاَيُّهَا الَّذِيْنَ اٰمَنُوا اجْتَنِبُوْا كَثِيْرًا مِّنَ الظَّنِّ ۫ اِنَّ بَعْضَ الظَّنِّ اِثْمٌ وَّلَا تَجَسَّسُوْا وَلَا يَغْتَبْ بَّعْضُكُمْ بَعْضًا ؕ اَيُحِبُّ اَحَدُكُمْ اَنْ يَّاْكُلَ لَحْمَ اَخِيْهِ مَيْتًا فَكَرِهْتُمُوْهُ ؕ وَاتَّقُوا اللّٰهَ ؕ اِنَّ اللّٰهَ تَوَّابٌ رَّحِيْمٌ', 'الحجرات: 12-11')
    P(b, [('Translation: Believers! Men should not mock (other) men; it is possible that those being mocked are better than them. Nor should women mock (other) women; it is possible that those being mocked are better than them. And do not find fault with one another, nor call one another by bad names. To give a bad name after believing is a sin. And those who do not repent, they are the wrongdoers.', 'ترجمہ: مومنو! مرد مردوں سے تمسخر نہ کریں ممکن ہے جن کا مذاق اڑایا جا رہا ہے ان سے بہتر ہوں اور نہ عورتیں عورتوں سے تمسخر کریں۔ ممکن ہے وہ جن کا مذاق اڑا رہی ہیں ان سے اچھی ہوں۔ اور اپنوں کو آپس میں عیب نہ لگاؤ اور نہ ایک دوسرے کا برا نام رکھو۔ ایمان لانے کے بعد برا نام رکھنا گناہ ہے۔ اور جو لوگ توبہ نہ کریں وہ ظالم ہیں۔', 'ژباړه: مؤمنانو! نارینه دې پر نارینه وو ملنډې نه وهي؛ کېدای شي هغوی چې پرې ملنډې وهل کېږي، تر دوی غوره وي. او نه دې ښځې پر ښځو ملنډې وهي؛ کېدای شي هغه چې پرې ملنډې وهي، تر دوی ښې وي. او یو بل ته عیب مه لګوئ او نه یو بل ته بد نومونه ږدئ. له ایمان راوړلو وروسته بد نوم ایښودل ګناه ده. او څوک چې توبه ونه باسي، همدوی ظالمان دي.'),
          ('O you who believe! Avoid much suspicion, for some suspicion is a sin; and do not spy into one another\'s affairs, and let none of you backbite anyone. Would any of you like to eat the flesh of his dead brother? You would surely hate it (so do not backbite) and fear Allah. Indeed Allah is the Accepter of repentance, the Merciful.', 'اے ایمان والو! بہت گمان کرنے سے پرہیز کرو کہ بعض گمان گناہ ہیں اور ایک دوسرے کے حال کا تجسس نہ کیا کرو اور نہ تم میں سے کوئی کسی کی غیبت کرے۔ کیا تم میں سے کوئی اس بات کو پسند کرے گا کہ اپنے مرے ہوئے بھائی کا گوشت کھائے؟ اس سے تو تم ضرور نفرت کرو گے (تو غیبت نہ کرو اور) اللہ سے ڈر رکھو بیشک اللہ توبہ قبول کرنے والا ہے مہربان ہے۔', 'اې مؤمنانو! له ډېر ګومان کولو ډډه وکړئ، ځکه ځینې ګومانونه ګناه دي؛ او د یو بل د حال جاسوسي مه کوئ، او ستاسو څوک دې د بل غیبت نه کوي. ایا ستاسو څوک دا خوښوي چې د خپل مړه ورور غوښه وخوري؟ له دې خو به خامخا کرکه وکړئ (نو غیبت مه کوئ) او له الله وډار اوسئ؛ بې‌شکه الله توبه منونکی، مهربان دی.'),
          ('Quranic teachings give the entire human society the lesson of complete protection of life and property. The unjust killing of one person has been declared the killing of humanity, and saving the life of one person has been described as saving the life of the whole of humanity.', 'قرآنی تعلیمات پورے انسانی معاشرے کو جان و مال کی مکمل حفاظت کا درس دیتی ہیں۔ کسی کے قتلِ ناحق کو انسانیت کا قتل قرار دیا گیا ہے۔ اور کسی کی جان بچانے کو پوری انسانیت کی جان بچانے سے تعبیر کیا گیا ہے۔', 'قرآني لارښوونې ټولې انساني ټولنې ته د ځان او مال د بشپړې ساتنې درس ورکوي. د یو چا ناحقه وژنه د انسانیت وژنه ګڼل شوې، او د یو چا د ژوند ژغورل د ټول انسانیت د ژوند ژغورلو په توګه بیان شوي.'),
          ('Islam does not only take responsibility for protecting life and property, but also grants open permission for freedom of thought and freedom of opinion. In this regard the teachings of Islam are very clear.', 'اسلام صرف جان و مال کی حفاظت کا ہی ذمہ نہیں لیتا بلکہ آزادیٔ فکر اور آزادیٔ رائے کی بھی کھلی اجازت مرحمت فرماتا ہے۔ اس ضمن میں اسلام کی تعلیمات بڑی واضح ہیں۔', 'اسلام یوازې د ځان او مال د ساتنې ذمه نه اخلي، بلکې د فکر او نظر ازادۍ ته هم پراخه اجازه ورکوي. په دې برخه کې د اسلام لارښوونې ډېرې روښانه دي.')])
    r1 = rec(b, 1, 64, 37, [64])
    t = Builder()
    t.p('The divine saying is:', 'ارشادِ ربانی ہے۔', 'الهي ارشاد دی:')
    AR(t, 'لَآ اِكْرَاهَ فِي الدِّيْنِ')
    P(t, [('Translation: There is no compulsion in religion.', 'ترجمہ: دین میں کوئی جبر نہیں۔', 'ژباړه: په دین کې هېڅ جبر نشته.'),
          ('The Noble Prophet ﷺ placed the foundation of Islamic society on mutual love and brotherhood. His ﷺ blessed saying is:', 'نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے اسلامی معاشرے کی اساس باہمی محبت و اخوت پر رکھی ہے۔ آپ صلی اللہ علیہ وآلہٖ وسلم کا ارشادِ گرامی ہے:', 'نبي اکرم ﷺ د اسلامي ټولنې بنسټ پر متقابلې مینې او ورورولۍ ایښی دی. د هغه ﷺ مبارک ارشاد دی:'),
          ('By God, no one can be a believer until he likes for his brother the same that he likes for himself.', 'خدا کی قسم اس وقت تک کوئی مومن نہیں ہو سکتا جب تک وہ اپنے بھائی کے لیے وہی پسند نہ کرے جو اپنے لیے کرتا ہے۔', 'په خدای قسم، هېڅوک تر هغو مؤمن کېدای نشي چې د خپل ورور لپاره هغه څه خوښ نه کړي چې د ځان لپاره یې خوښوي.'),
          ('He ﷺ said that you people will not enter Paradise until you bring faith, and (you will not be believers) until you begin to love one another. (Sahih Muslim: 203)', 'آپ صلی اللہ علیہ وآلہٖ وسلم نے ارشاد فرمایا کہ تم لوگ اس وقت تک جنت میں داخل نہ ہو گے جب تک ایمان نہ لے آؤ اور جب تک آپس میں محبت نہ کرنے لگو۔ (صحیح مسلم: 203)', 'هغه ﷺ وفرمایل چې تاسو خلک به تر هغو جنت ته ننوځئ نه چې ایمان راوړئ، او تر څو مو چې په خپل منځ کې مینه پیل کړې نه وي. (صحیح مسلم: ۲۰۳)'),
          ('Huzoor, the Noble Prophet ﷺ, did not only give the lesson of mutual love; rather he ﷺ also forbade Muslims from backbiting one another and from slandering.', 'حضور نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے صرف باہمی محبت کا درس ہی نہیں دیا بلکہ آپ صلی اللہ علیہ وآلہٖ وسلم نے مسلمانوں کو ایک دوسرے کی غیبت کرنے اور بہتان لگانے سے بھی منع فرمایا۔', 'حضور نبي کریم ﷺ یوازې د متقابلې مینې درس نه دی ورکړی، بلکې مسلمانان یې د یو بل له غیبت او تهمت لګولو هم منع کړي.')])
    AR(t, 'عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللّٰهُ عَنْهُ، اَنَّ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ قَالَ: "اَتَدْرُوْنَ مَا الْغِيْبَةُ؟" قَالُوْا: اَللّٰهُ وَرَسُوْلُهٗ اَعْلَمُ. قَالَ: "ذِكْرُكَ اَخَاكَ بِمَا يَكْرَهُ" قِيْلَ: اَفَرَاَيْتَ اِنْ كَانَ فِيْ اَخِيْ مَا اَقُوْلُ؟ قَالَ: "اِنْ كَانَ فِيْهِ مَا تَقُوْلُ، فَقَدِ اغْتَبْتَهٗ، وَاِنْ لَّمْ يَكُنْ فِيْهِ مَا تَقُوْلُ فَقَدْ بَهَتَّهٗ"', 'رواہ مسلم')
    P(t, [('Translation: It is narrated from Abu Hurayrah (may Allah be pleased with him) that the Messenger of Allah ﷺ said: "Do you know what backbiting is?" The Companions submitted: Allah and His Messenger know best. The Noble Prophet ﷺ said: "Mentioning your brother in such a manner that he would dislike." The Noble Prophet ﷺ was asked: tell (us), if that thing is present in my brother which I mention? The Holy Messenger ﷺ said: "If that thing is present in him which you mention, then certainly you have backbitten him; and if that matter is not in him which you state about him, then you have slandered him."', 'ترجمہ: ابوہریرۃ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: ”کیا تم جانتے ہو غیبت کیا ہے؟“ صحابہ نے عرض کیا: اللہ اور اس کا رسول ہی بہتر جانتے ہیں۔ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا ”تیرے اپنے بھائی کا ایسے انداز میں ذکر کرنا جسے وہ پسند نہ کرے۔“ نبی کریم صلی اللہ علیہ وآلہٖ وسلم سے پوچھا گیا: یہ بتلائیے کہ اگر میرے بھائی میں وہ چیز موجود ہو جس کا میں ذکر کروں؟ تو رسول پاک صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: ”اگر اس میں وہ چیز موجود ہو جس کا ذکر تو کرے تو یقیناً تو نے غیبت کی اور اگر اس میں وہ بات نہیں ہے جو تو اس کی بابت بیان کرے تو پھر تو نے اس پر بہتان باندھا ہے۔“', 'ژباړه: له ابوهریره رضي الله عنه روایت دی چې د الله رسول ﷺ وفرمایل: «ایا پوهېږئ چې غیبت څه دی؟» صحابه وو عرض وکړ: الله او د هغه رسول ښه پوهېږي. نبي کریم ﷺ وفرمایل: «د خپل ورور داسې یادونه چې هغه یې نه خوښوي.» له نبي کریم ﷺ وپوښتل شول: ووایه، که زما په ورور کې هغه شی موجود وي چې زه یې یادوم؟ رسول پاک ﷺ وفرمایل: «که په هغه کې هغه شی موجود وي چې ته یې یادوې، نو خامخا دې غیبت وکړ؛ او که په هغه کې هغه خبره نه وي چې ته یې د هغه په اړه بیانوې، نو تا پرې تهمت تړلی دی.»')])
    BOOK.save(37, [(1, r1), (1, rec(t, 1, 65, 37, [65]))], issues=[{'id': 'iski12-pdf037', 'unit': 1, 'printedPage': 64,
               'description': 'Verse reference printed as "الحجرات:12-11" — kept as printed. «لا اکراہ فی الدین» (Al-Baqarah 256) is printed without a reference — kept without one. Student handwriting in the margins of pp.64–65 excluded.'}])


if __name__ == '__main__':
    p37()
